SELECT 'batch_032_60e8f228_wav_10' AS batch_id,(SELECT COUNT(*) FROM c) AS expected_masters,(SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-f104690a5b024491962419b76618435d' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1) AS exact_pending_storage_matches,(SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-f104690a5b024491962419b76618435d' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1) AS metadata_snapshot_matches,(SELECT COUNT(*) FROM albums WHERE id='al-18ec76e1cfd7e7dc3e8258b060e8f228') AS target_album_rows,(SELECT COUNT(*) FROM (SELECT lower(trim(sm.title)) FROM c JOIN song_masters sm ON sm.id=c.master_id GROUP BY lower(trim(sm.title)) HAVING COUNT(*)>1)) AS duplicate_title_groups,(SELECT COUNT(*) FROM (SELECT COALESCE(sm.disc,0),sm.track FROM c JOIN song_masters sm ON sm.id=c.master_id WHERE sm.track IS NOT NULL GROUP BY COALESCE(sm.disc,0),sm.track HAVING COUNT(*)>1)) AS duplicate_disc_track_groups,(SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-f104690a5b024491962419b76618435d' AND sm.album_id!='pending-uploads') AS other_album_members,(SELECT COUNT(*) FROM storage_entries se JOIN song_instances si ON si.id=se.instance_id AND si.source_id='r2-local' AND lower(si.suffix)='wav' JOIN song_masters sm ON sm.id=si.master_id WHERE se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-f104690a5b024491962419b76618435d' AND sm.album_id!='pending-uploads' AND sm.id NOT IN ('')) AS unallowlisted_other_members,(SELECT COUNT(*) FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE sm.id IN ('') AND sm.album_id IN ('') AND se.source_id='r2-local' AND se.parent_id='se-f104690a5b024491962419b76618435d' AND lower(si.suffix)='wav') AS allowlisted_other_members;
